var n=`0300-byrek-me-spinaq`;var t=`world-0300`;var a=`AL`;var o=`southern-europe`;var l=4;var r=58;var s={en:`Byrek me Spinaq`,ua:`Бюрек зі шпинатом`};var g={en:`A traditional Albania dish made with spinach, yellow onion, dill, feta. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Албанія. Основні інгредієнти: шпинат, жовта цибуля, кріп, фета. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`spinach`,680,`g`],[`yellow-onion`,160,`g`],[`extra-virgin-olive-oil`,35,`ml`],[`dill`,12,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`feta`,210,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`phyllo-pastry`,400,`g`],[`extra-virgin-olive-oil`,85,`ml`]]},{en:`Bake in a preheated 180°C oven for about 33 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 33 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:33,i:[]}];var h={slug:n,id:t,country:`AL`,region:o,servings:4,minutes:58,title:s,text:g,steps:d};export{a as country,h as default,t as id,r as minutes,o as region,l as servings,n as slug,d as steps,g as text,s as title};